--
-- Range below 1000 is reserved for technical purposes!
-- These person/users are created manually because the application relies on the user_id.
--
-- Any "real" users must be included in the csv file, and generated by GDI. See:
--   logon-persistence/etc/csv/initialdata/user_person_driver_role.csv
-- Those user_id are given by a DB sequence number

prompt '---------- initialdata/technical_user_person_driver_role.sql ----------'

prompt INSERTING technical user 'system'

---- Person data of Technical users
-- Technical persons are set as inactive, and must not be shown in selection in UI normally!
-- For now, only one, but extend to different ones, in case different subsystems should be distinguished.

insert into tlgnc_person (
  person_id, name, firstname, phone_nr, mobile_nr, email, active_flag,
  ctl_cre_uid, ctl_cre_ts, ctl_mod_uid, ctl_mod_ts, ctl_tcn
) values (
  1, 'system', 'system', null, null, 'logon-ch@crh.com', 0,
  1, systimestamp, 1, systimestamp, 0
);

insert into tlgnu_user (
  user_id, person_id, user_type_cd,
  sap_bp_id, sap_vendor_id,
  ldap_holspace,
  ext_login_active_flag, ext_login, ext_login_pwd, ext_login_pwd_valid_to_dat,
  pda_user_no, pda_user_rfidobject_id, pda_pin, pda_pin_valid_to_dat,
  photo_image_id, signature_id, signature_valid_flag, application_lang_cd,
  send_daily_reports_flag,
  ctl_cre_uid, ctl_cre_ts, ctl_mod_uid, ctl_mod_ts, ctl_tcn
) values (
  1, 1, 0,
  null, null,
  null,
  0, null, null, null,
  null, null, null, null,
  null, null, null, 'en',
  0,
  1, systimestamp, 1, systimestamp, 0
);

-- Current concept does NOT give any roles to the technical users.
-- Maybe this will be necessary in the future, in case a certain service checks authorization as well, and does not handle technical users specially.

commit;
